/* ── INTERACTIVE MACHINE PARAMETER STEPPERS ── */
/* ── DIGITAL TWIN LIVE PERFORMANCE & OPERATIONAL COST ENGINE ── */
function updateDigitalTwinMetrics() {
    var feedRate = pipelineParams.feed_rate || 120;
    var cncSpeed = pipelineParams.cnc_speed || 92;
    var torque = pipelineParams.torque || 185;
    var takt = bomParams.takt || 18;

    // 1. Daily Finished Valve Output
    // Baseline: feedRate=120, cncSpeed=92, takt=18 => 120 valves/day
    var dailyThroughput = Math.round(feedRate * (cncSpeed / 92.0) * (18.0 / takt));
    if (dailyThroughput < 20) dailyThroughput = 20;

    // 2. Shift Operating & Energy Cost
    // Baseline: Rs 88,400 per shift
    var speedDeltaCost = (cncSpeed - 92) * 520;
    var torqueDeltaCost = (torque - 185) * 140;
    var feedDeltaCost = (feedRate - 120) * 180;
    var shiftOperatingCost = Math.round(88400 + speedDeltaCost + torqueDeltaCost + feedDeltaCost);
    if (shiftOperatingCost < 40000) shiftOperatingCost = 40000;

    // 3. Inventory Valuation
    var bodiesVal = (bomParams.bodies || 0) * 12500;
    var stemsVal = (bomParams.stems || 0) * 3200;
    var seatsVal = (bomParams.seats || 0) * 4800;
    var boltsVal = (bomParams.bolts || 0) * 850;
    var totalInventoryVal = bodiesVal + stemsVal + seatsVal + boltsVal;
    var invInLakhs = (totalInventoryVal / 100000.0).toFixed(2);

    // 4. Runout Horizon
    var limitingUnits = Math.min(bomParams.bodies || 0, bomParams.stems || 0, bomParams.seats || 0);
    var bottleneckItem = "Bodies";
    if (bomParams.stems <= bomParams.bodies && bomParams.stems <= bomParams.seats) {
        bottleneckItem = "SS 316 Stems (" + bomParams.stems + " U)";
    } else if (bomParams.bodies <= bomParams.stems && bomParams.bodies <= bomParams.seats) {
        bottleneckItem = "Cast Bodies (" + bomParams.bodies + " U)";
    } else {
        bottleneckItem = "Seat Rings (" + bomParams.seats + " U)";
    }

    var runoutDays = (limitingUnits / (dailyThroughput > 0 ? dailyThroughput : 1)).toFixed(2);

    // Update DOM elements in View 2
    var dtTp = document.getElementById('dtThroughput');
    if (dtTp) dtTp.innerText = dailyThroughput + ' Valves / Day';
    var bTp = document.getElementById('badgeThroughputDelta');
    if (bTp) {
        var diff = dailyThroughput - 120;
        bTp.innerText = (diff >= 0 ? '+' : '') + diff + ' vs Baseline';
        bTp.style.color = diff >= 0 ? 'var(--status-normal)' : 'var(--status-alert)';
    }

    var dtSc = document.getElementById('dtShiftCost');
    if (dtSc) dtSc.innerHTML = '&#8377;' + shiftOperatingCost.toLocaleString('en-IN') + ' / Shift';
    var bSc = document.getElementById('badgeCostDelta');
    if (bSc) {
        var costDiff = shiftOperatingCost - 88400;
        bSc.innerText = (costDiff >= 0 ? '+' : '') + '&#8377;' + costDiff.toLocaleString('en-IN');
        bSc.style.color = costDiff <= 0 ? 'var(--status-normal)' : 'var(--status-amber)';
    }

    var dtIv = document.getElementById('dtInventoryValue');
    if (dtIv) dtIv.innerHTML = '&#8377;' + invInLakhs + ' Lakhs';
    var dtIb = document.getElementById('dtInventoryBreakdown');
    if (dtIb) dtIb.innerText = bomParams.bodies + ' Bodies, ' + bomParams.stems + ' Stems, ' + bomParams.seats + ' Seats';

    var dtRh = document.getElementById('dtRunoutHorizon');
    if (dtRh) dtRh.innerText = runoutDays + ' Days Buffer';
    var dtBn = document.getElementById('dtBottleneckItem');
    if (dtBn) dtBn.innerText = 'Bottleneck: ' + bottleneckItem;
    var bHz = document.getElementById('badgeHorizonDelta');
    if (bHz) {
        if (runoutDays < 0.6) {
            bHz.innerText = 'CRITICAL DEFICIT';
            bHz.style.color = 'var(--status-alert)';
        } else if (runoutDays < 1.0) {
            bHz.innerText = 'Tight Reserve';
            bHz.style.color = 'var(--status-amber)';
        } else {
            bHz.innerText = 'Optimal Horizon';
            bHz.style.color = 'var(--status-normal)';
        }
    }

    var pPill = document.getElementById('pipelineFlowRatePill');
    if (pPill) {
        pPill.innerHTML = '&#10004; Flow Rate: ' + dailyThroughput + ' U/day &#8226; Steady';
    }
}

/* ── INTERACTIVE MACHINE PARAMETER STEPPERS ── */
function adjustMachineParam(paramId, delta, unit) {
    if (typeof pipelineParams[paramId] === 'undefined') return;
    pipelineParams[paramId] += delta;
    if (paramId === 'feed_rate' && pipelineParams[paramId] < 30) pipelineParams[paramId] = 30;
    if (paramId === 'cnc_speed' && pipelineParams[paramId] < 50) pipelineParams[paramId] = 50;
    if (paramId === 'torque' && pipelineParams[paramId] < 100) pipelineParams[paramId] = 100;
    if (paramId === 'pressure' && pipelineParams[paramId] < 100) pipelineParams[paramId] = 100;
    if (paramId === 'dispatch_batch' && pipelineParams[paramId] < 10) pipelineParams[paramId] = 10;

    var el = document.getElementById('val_' + paramId);
    if (el) el.innerText = pipelineParams[paramId] + unit;

    if (paramId === 'torque') {
        var tDisp = document.getElementById('disp_torque');
        if (tDisp) tDisp.innerText = pipelineParams[paramId] + ' Nm';
    }
    if (paramId === 'pressure') {
        var pDisp = document.getElementById('disp_pressure');
        if (pDisp) pDisp.innerText = pipelineParams[paramId] + ' Bar';
    }

    updateDigitalTwinMetrics();
    showToast('✔ ' + paramId.replace('_', ' ').toUpperCase() + ' adjusted to ' + pipelineParams[paramId] + unit + ' — Live stats & costs recalculated');
}

/* ── INTERACTIVE COMPONENT & BOM PARAMETER STEPPERS ── */
function adjustBOMParam(paramId, delta, unit) {
    if (typeof bomParams[paramId] === 'undefined') return;
    bomParams[paramId] += delta;
    if (bomParams[paramId] < 0) bomParams[paramId] = 0;

    var el = document.getElementById('val_bom_' + paramId);
    if (el) el.innerText = bomParams[paramId] + unit;

    var statusEl = document.getElementById('bom_status_' + paramId);
    if (statusEl) {
        if (bomParams[paramId] < 40) {
            statusEl.innerText = 'CRITICAL DEFICIT';
            statusEl.style.color = 'var(--status-alert)';
        } else if (bomParams[paramId] < 80) {
            statusEl.innerText = 'Low Buffer';
            statusEl.style.color = 'var(--status-amber)';
        } else {
            statusEl.innerText = 'Safe Reserve';
            statusEl.style.color = 'var(--status-normal)';
        }
    }

    updateDigitalTwinMetrics();
    showToast('✔ BOM ' + paramId.toUpperCase() + ' updated: ' + bomParams[paramId] + unit + ' — Inventory capital & horizon synced');
}

function resetBOMParams() {
    bomParams = { bodies: 140, stems: 95, seats: 210, bolts: 320, takt: 18 };
    ['bodies', 'stems', 'seats', 'bolts', 'takt'].forEach(function(k) {
        var el = document.getElementById('val_bom_' + k);
        var u = (k === 'bolts' ? ' Sets' : (k === 'takt' ? ' min' : ' U'));
        if (el) el.innerText = bomParams[k] + u;
        var s = document.getElementById('bom_status_' + k);
        if (s) { s.innerText = 'Safe Reserve'; s.style.color = 'var(--status-normal)'; }
    });
    updateDigitalTwinMetrics();
    showToast('✔ Component BOM inventory reset to standard safe reserves');
}

/* ── VIEW SWITCHER ── */
function switchView(viewId, clickedLink) {
    document.querySelectorAll('.page-view').forEach(function(v) {
        v.classList.remove('active-view');
    });
    var targetView = document.getElementById(viewId);
    if (targetView) targetView.classList.add('active-view');

    if (clickedLink) {
        document.querySelectorAll('.sidebar-link').forEach(function(l) {
            l.classList.remove('active');
        });
        clickedLink.classList.add('active');
    } else {
        var tabMap = {
            'view-overview': 'tab-overview',
            'view-pipeline': 'tab-pipeline',
            'view-simulator': 'tab-simulator',
            'view-machines': 'tab-machines',
            'view-analytics': 'tab-analytics',
            'view-orders': 'tab-orders'
        };
        var tabId = tabMap[viewId];
        if (tabId) {
            document.querySelectorAll('.sidebar-link').forEach(function(l) {
                l.classList.remove('active');
            });
            var t = document.getElementById(tabId);
            if (t) t.classList.add('active');
        }
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

/* ── RENDER WORK CENTERS (WITH REAL MACHINE SVGS & ONE-CLICK MAINTENANCE DISPATCH) ── */
function renderMachines() {
    var machGrid = document.getElementById('gridMachining');
    var asyGrid  = document.getElementById('gridAssembly');
    var tstGrid  = document.getElementById('gridTesting');
    var rwkGrid  = document.getElementById('gridRework');

    if (!machGrid) return;
    machGrid.innerHTML = '';
    if (asyGrid) asyGrid.innerHTML = '';
    if (tstGrid) tstGrid.innerHTML = '';
    if (rwkGrid) rwkGrid.innerHTML = '';

    var countMach = 0, countAsy = 0, countTst = 0, countRwk = 0;

    machines.forEach(function(m) {
        if (currentFacilityFilter !== 'ALL' && m.facility !== currentFacilityFilter) {
            return;
        }

        var pillClass = 'chip-ok';
        var pillText = 'OPTIMAL';
        var borderStyle = 'border: 1px solid var(--border-medium);';

        if (m.dispatched) {
            pillClass = 'chip-ok';
            pillText = 'WORK ORDER ACTIVE';
            borderStyle = 'border: 1.5px solid #047857; background: #f0fdf4;';
        } else if (m.status === 'repair' || (m.code === 'MC-HYD-CNC-02' && currentScenarioKey === 'SIM-2026-001')) {
            pillClass = 'chip-bottleneck';
            pillText = 'DOWN (0h)';
            borderStyle = 'border: 1px solid var(--status-alert-border); background: var(--status-alert-bg);';
        } else if (m.status === 'alert') {
            pillClass = 'stage-status-chip chip-bottleneck';
            pillText = 'ALERT';
            borderStyle = 'border: 1px solid var(--status-amber-border);';
        } else if (m.status === 'warning') {
            pillClass = 'stage-status-chip';
            pillText = 'WARNING';
        }

        if (m.code === 'MC-HYD-CNC-01' && currentScenarioKey === 'SIM-2026-001') {
            pillClass = 'chip-active';
            pillText = 'REROUTED (+4h OT)';
            borderStyle = 'border: 1px solid var(--brand-blue-border); background: #f8fafc;';
        }

        // Maintenance Dispatch Button
        var maintBtnHtml = '';
        if (m.dispatched) {
            maintBtnHtml = '<div class="btn-maint-active">&#10004; Maintenance Dispatched (' + (m.incidentRef || 'INC0010892') + ')</div>';
        } else if (m.status === 'alert' || m.status === 'repair' || (m.code === 'MC-HYD-CNC-02' && currentScenarioKey === 'SIM-2026-001')) {
            maintBtnHtml = '<button class="btn-dispatch-maint" onclick="openMaintenanceModal(\'' + m.code + '\')">&#9889; Dispatch Emergency Maintenance</button>';
        } else if (m.status === 'warning') {
            maintBtnHtml = '<button class="btn-dispatch-maint" style="background: #fffbeb; border-color: #fde68a; color: #b45309;" onclick="openMaintenanceModal(\'' + m.code + '\')">&#9888; Schedule Preventive Work Order</button>';
        } else {
            maintBtnHtml = '<button class="btn-inspect-subtle" onclick="openMaintenanceModal(\'' + m.code + '\')">&#128295; Create Maintenance Request</button>';
        }

        // Machine SVG image
        var svgImg = machineSVGs[m.imgType] || machineSVGs['CNC_MILL'];

        var cardHtml =
            '<div style="' + borderStyle + ' border-radius: var(--radius-sm); padding: 16px 18px; background: #ffffff; display: flex; flex-direction: column; justify-content: space-between;">' +
            '  <div>' +
            '    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">' +
            '      <strong style="font-family: var(--font-mono); font-size: 11.5px; color: var(--brand-navy);">' + m.code + '</strong>' +
            '      <span class="stage-status-chip ' + pillClass + '">' + pillText + '</span>' +
            '    </div>' +
            '    <div style="font-size: 13.5px; font-weight: 700; color: var(--text-primary); margin-bottom: 8px;">' + m.name + '</div>' +
            '    <div style="margin-bottom: 10px; border-radius: 4px; overflow: hidden; background: #0f2438;">' +
                   svgImg +
            '    </div>' +
            '    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px; background: #f8fafc; padding: 10px 12px; border-radius: 4px; border: 1px solid #e2e8f0; margin-bottom: 12px;">' +
            '      <div><span style="color: var(--text-muted);">Temp:</span> <strong id="temp_' + m.code + '">' + m.temp + '&#176;C</strong></div>' +
            '      <div><span style="color: var(--text-muted);">Vibration:</span> <strong>' + m.vib + ' mm/s</strong></div>' +
            '      <div><span style="color: var(--text-muted);">Plant:</span> <strong>' + m.facility + '</strong></div>' +
            '      <div><span style="color: var(--text-muted);">Crew:</span> <strong>' + m.crew.split(' ')[0] + ' ' + m.crew.split(' ')[1] + '</strong></div>' +
            '    </div>' +
            '    <div>' +
            '      <div style="display: flex; justify-content: space-between; font-size: 11.5px; color: var(--text-muted); margin-bottom: 5px;"><span>Capacity Load</span><strong>' + m.load + '%</strong></div>' +
            '      <div style="height: 6px; background: #e2e8f0; border-radius: 3px; overflow: hidden;"><div style="height: 100%; width: ' + m.load + '%; background: var(--brand-navy);"></div></div>' +
            '    </div>' +
            '  </div>' +
            '  <div>' + maintBtnHtml + '</div>' +
            '</div>';

        if (m.category === 'Machining' && machGrid) { machGrid.innerHTML += cardHtml; countMach++; }
        else if (m.category === 'Assembly' && asyGrid) { asyGrid.innerHTML += cardHtml; countAsy++; }
        else if (m.category === 'Testing' && tstGrid) { tstGrid.innerHTML += cardHtml; countTst++; }
        else if (m.category === 'Rework' && rwkGrid) { rwkGrid.innerHTML += cardHtml; countRwk++; }
    });

    var el;
    el = document.getElementById('countMachining'); if (el) el.innerText = countMach + ' Centers';
    el = document.getElementById('countAssembly');  if (el) el.innerText = countAsy + ' Centers';
    el = document.getElementById('countTesting');   if (el) el.innerText = countTst + ' Centers';
    el = document.getElementById('countRework');    if (el) el.innerText = countRwk + ' Center';
}

