/* ── MULTI-STRATEGY COMPARISON MATRIX ── */
function renderStrategyMatrix() {
    var grids = [document.getElementById('strategyMatrixGrid'), document.getElementById('strategyMatrixGridAnalytics')];
    var badge = document.getElementById('activeStrategyBadge');
    if (badge && strategiesConfig[currentStrategyKey]) {
        badge.innerText = 'Active: ' + strategiesConfig[currentStrategyKey].name;
    }

    grids.forEach(function(container) {
        if (!container) return;
        var html = '';
        ['A', 'B', 'C'].forEach(function(key) {
            var s = strategiesConfig[key];
            var isSel = (currentStrategyKey === key);
            var cardClass = isSel ? 'strategy-choice-card selected-strategy' : 'strategy-choice-card';

            html += '<div class="' + cardClass + '" onclick="applyStrategy(\'' + key + '\')">' +
                '  <div>' +
                '    <div class="strategy-top-header">' +
                '      <span class="strategy-pill ' + s.tagClass + '">' + s.badge + '</span>' +
                (isSel ? '      <span class="stage-status-chip chip-ok" style="font-size: 10.5px;">ACTIVE SELECTION</span>' : '') +
                '    </div>' +
                '    <div style="font-size: 14px; font-weight: 700; color: var(--brand-navy); margin-bottom: 6px;">' + s.name + '</div>' +
                '    <div style="font-size: 12px; color: var(--text-secondary); line-height: 1.45; margin-bottom: 10px;">' + s.desc + '</div>' +
                '  </div>' +
                '  <div>' +
                '    <div class="strategy-stat-grid">' +
                '      <div class="strategy-stat-item"><span class="strategy-stat-label">Delta Cost</span><span class="strategy-stat-val">' + s.cost + '</span></div>' +
                '      <div class="strategy-stat-item"><span class="strategy-stat-label">Mitigated OTD</span><span class="strategy-stat-val" style="color: var(--status-normal);">' + s.otd + '</span></div>' +
                '      <div class="strategy-stat-item"><span class="strategy-stat-label">OTD Recovery</span><span class="strategy-stat-val" style="color: var(--status-normal);">' + s.recovery + '</span></div>' +
                '      <div class="strategy-stat-item"><span class="strategy-stat-label">Speed</span><span class="strategy-stat-val">' + s.speed + '</span></div>' +
                '    </div>' +
                '    <div style="font-size: 11.5px; color: var(--text-muted); font-style: italic; margin-bottom: 12px;">' + s.tradeoff + '</div>' +
                '    <button class="' + (isSel ? 'btn-solid-blue' : 'btn-outline-green') + '" style="width: 100%; justify-content: center; padding: 7px 12px; font-size: 12px;" onclick="event.stopPropagation(); applyStrategy(\'' + key + '\')">' +
                (isSel ? '&#10004; Currently Applied' : 'Apply ' + s.name.split(':')[0]) +
                '    </button>' +
                '  </div>' +
                '</div>';
        });
        container.innerHTML = html;
    });
}

function applyStrategy(stratKey) {
    currentStrategyKey = stratKey;
    var s = strategiesConfig[stratKey];
    if (!s) return;

    var sc = scenariosData[currentScenarioKey];
    if (sc) {
        sc.optimized = s.otdNum;
        sc.cost = s.cost;
        sc.recovery = s.recovery;
        sc.strategy = s.desc;
    }

    // Update readouts
    ['kpiOptimized', 'kpiOptimizedOverview'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.innerText = s.otd + ' (' + s.recovery + ' Delay Recovered)';
    });
    ['barOptimized', 'barOptimizedOverview'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.width = s.otd;
    });

    var kpiAdapted = document.getElementById('kpiAdaptedOTD');
    if (kpiAdapted) kpiAdapted.innerText = s.otd;
    var st = document.getElementById('strategyText');
    if (st) st.innerHTML = s.desc;
    var scost = document.getElementById('stratCost');
    if (scost) scost.innerHTML = s.cost;
    var analyticsCost = document.getElementById('analyticsDeltaCost');
    if (analyticsCost) analyticsCost.innerHTML = s.cost;

    renderStrategyMatrix();
    showToast('\u2714 Strategy ' + stratKey + ' Applied: ' + s.name.split(':')[0] + ' (' + s.otd + ' OTD)');
}

/* ── SCENARIO LOADER ── */
