    el = document.getElementById('targetAsset'); if (el) el.value = sc.asset;
    el = document.getElementById('simViewAsset'); if (el) el.value = sc.asset;

    el = document.getElementById('durationSlider'); if (el) el.value = sc.duration;
    el = document.getElementById('simViewDurationSlider'); if (el) el.value = sc.duration;
    el = document.getElementById('durationLabel'); if (el) el.innerText = sc.duration + 'h';
    el = document.getElementById('simViewDurationLabel'); if (el) el.innerText = sc.duration + 'h';

    el = document.getElementById('capacitySlider'); if (el) el.value = sc.cap;
    el = document.getElementById('simViewCapacitySlider'); if (el) el.value = sc.cap;
    el = document.getElementById('capacityLabel'); if (el) el.innerText = sc.cap + '%';
    el = document.getElementById('simViewCapacityLabel'); if (el) el.innerText = sc.cap + '%';

    // Update Analytics elements
    ['kpiBaseline', 'kpiBaselineOverview'].forEach(function(id) {
        var b = document.getElementById(id); if (b) b.innerText = sc.baseline + '%';
    });
    ['kpiSimulated', 'kpiSimulatedOverview'].forEach(function(id) {
        var s = document.getElementById(id); if (s) s.innerText = sc.simulated + '% (-' + sc.drop + ' Drop)';
    });
    ['kpiOptimized', 'kpiOptimizedOverview'].forEach(function(id) {
        var o = document.getElementById(id); if (o) o.innerText = sc.optimized + '% (' + sc.recovery + ' Delay Recovered)';
    });

    ['barBaseline', 'barBaselineOverview'].forEach(function(id) {
        var b = document.getElementById(id); if (b) b.style.width = sc.baseline + '%';
    });
    ['barSimulated', 'barSimulatedOverview'].forEach(function(id) {
        var s = document.getElementById(id); if (s) s.style.width = sc.simulated + '%';
    });
    ['barOptimized', 'barOptimizedOverview'].forEach(function(id) {
        var o = document.getElementById(id); if (o) o.style.width = sc.optimized + '%';
    });

    // Top KPI Cards
    var dropKpi = document.getElementById('kpiUnmitigatedDrop');
    if (dropKpi) dropKpi.innerText = '-' + sc.drop;
    var optKpi = document.getElementById('kpiAdaptedOTD');
    if (optKpi) optKpi.innerText = sc.optimized + '%';

    // Strategy text
    var st = document.getElementById('strategyText');
    if (st) st.innerHTML = sc.strategy;
    var sr = document.getElementById('stratRecovery');
    if (sr) sr.innerText = sc.recovery;
    var sp = document.getElementById('stratProtected');
    if (sp) sp.innerText = sc.orders.length + ' Orders';
    var scost = document.getElementById('stratCost');
    if (scost) scost.innerHTML = sc.cost;

    renderOrders();
    renderMachines();
    renderStrategyMatrix();
    showToast('Loaded Scenario: ' + sc.modelName);
}

/* ── DYNAMIC SLIDER HANDLERS WITH LIVE RECALCULATION ── */
function onDurationSlider(val) {
    var el1 = document.getElementById('durationLabel'); if (el1) el1.innerText = val + 'h';
    var el2 = document.getElementById('simViewDurationLabel'); if (el2) el2.innerText = val + 'h';
    var s1 = document.getElementById('durationSlider'); if (s1) s1.value = val;
    var s2 = document.getElementById('simViewDurationSlider'); if (s2) s2.value = val;
    recalculateLiveImpact();
}

function onCapacitySlider(val) {
    var el1 = document.getElementById('capacityLabel'); if (el1) el1.innerText = val + '%';
    var el2 = document.getElementById('simViewCapacityLabel'); if (el2) el2.innerText = val + '%';
    var s1 = document.getElementById('capacitySlider'); if (s1) s1.value = val;
    var s2 = document.getElementById('simViewCapacitySlider'); if (s2) s2.value = val;
    recalculateLiveImpact();
}

function recalculateLiveImpact() {
    var dSlider = document.getElementById('durationSlider');
    var cSlider = document.getElementById('capacitySlider');
    var duration = dSlider ? parseInt(dSlider.value) : 48;
    var capLost = cSlider ? parseInt(cSlider.value) : 100;

    var baseDrop = (duration / 48.0) * (capLost / 100.0) * 22.5;
    baseDrop = Math.min(Math.max(baseDrop, 5.0), 38.0);
    var simulatedOTD = (96.5 - baseDrop).toFixed(1);
    var recoveryFactor = 0.93;
    var adaptedOTD = (parseFloat(simulatedOTD) + (baseDrop * recoveryFactor)).toFixed(1);
    if (parseFloat(adaptedOTD) > 96.5) adaptedOTD = '96.5';

    // ── DYNAMIC FINANCIAL & COST CALCULATIONS ──
    var penaltyRatePerHour = 10875;
    var penaltyAmount = Math.round(duration * (capLost / 100.0) * penaltyRatePerHour);

    var deltaCostAmount = Math.round(duration * 875);
    if (currentStrategyKey === 'B') deltaCostAmount = Math.round(duration * 1350); // External subcontractor
    if (currentStrategyKey === 'C') deltaCostAmount = Math.round(duration * 180);  // Low-tier batch delay

    var netSavingsAmount = penaltyAmount - deltaCostAmount;
    if (netSavingsAmount < 0) netSavingsAmount = 0;
    var roiMultiplier = (deltaCostAmount > 0 ? (penaltyAmount / deltaCostAmount).toFixed(1) : '10.0');

    var costStr = '&#8377;' + deltaCostAmount.toLocaleString('en-IN');
    var penaltyStr = '&#8377;' + penaltyAmount.toLocaleString('en-IN');
    var savingsStr = '&#8377;' + netSavingsAmount.toLocaleString('en-IN');

    // 1. View 1 (Adaptive Mitigation Strategy card)
    var scost = document.getElementById('stratCost');
    if (scost) scost.innerHTML = costStr;

    // 2. View 3 (What-If Disruption Simulator card)
    var simPen = document.getElementById('simPenaltyCost');
    if (simPen) simPen.innerHTML = penaltyStr;
    var simDel = document.getElementById('simDeltaCost');
    if (simDel) simDel.innerHTML = costStr;
    var simNet = document.getElementById('simNetSavings');
    if (simNet) simNet.innerHTML = savingsStr;
    var simRoi = document.getElementById('simRoiMultiplier');
    if (simRoi) simRoi.innerText = roiMultiplier + 'x Simulation ROI';
    var simMotd = document.getElementById('simMitigatedOTD');
    if (simMotd) simMotd.innerText = adaptedOTD + '%';
    var simRec = document.getElementById('simRecoveryDelta');
    if (simRec) simRec.innerText = '+' + (baseDrop * recoveryFactor).toFixed(1) + '% Recovery';

    var sBarDrop = document.getElementById('simBarDrop');
    if (sBarDrop) sBarDrop.style.width = simulatedOTD + '%';
    var sBarDropText = document.getElementById('simBarDropText');
    if (sBarDropText) sBarDropText.innerText = simulatedOTD + '% (-' + baseDrop.toFixed(1) + '% Drop)';

    var sBarAdapted = document.getElementById('simBarAdapted');
    if (sBarAdapted) sBarAdapted.style.width = adaptedOTD + '%';
    var sBarAdaptedText = document.getElementById('simBarAdaptedText');
    if (sBarAdaptedText) sBarAdaptedText.innerText = adaptedOTD + '% (+' + (baseDrop * recoveryFactor).toFixed(1) + '% Recovered)';

    // 3. View 5 (Analytics Page)
    var anDel = document.getElementById('analyticsDeltaCost');
    if (anDel) anDel.innerHTML = costStr;
    var anPen = document.getElementById('analyticsPenaltyCost');
    if (anPen) anPen.innerHTML = penaltyStr;
    var anNet = document.getElementById('analyticsNetValue');
    if (anNet) anNet.innerHTML = savingsStr;

    // 4. Update Overview KPI Bars
    ['kpiSimulated', 'kpiSimulatedOverview'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.innerText = simulatedOTD + '% (-' + baseDrop.toFixed(1) + '% Drop)';
    });
    ['barSimulated', 'barSimulatedOverview'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.width = simulatedOTD + '%';
    });

    ['kpiOptimized', 'kpiOptimizedOverview'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.innerText = adaptedOTD + '% (+' + (baseDrop * recoveryFactor).toFixed(1) + '% Delay Recovered)';
    });
    ['barOptimized', 'barOptimizedOverview'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.width = adaptedOTD + '%';
    });

    var kpiDrop = document.getElementById('kpiUnmitigatedDrop');
    if (kpiDrop) kpiDrop.innerText = '-' + baseDrop.toFixed(1) + '%';
    var kpiAdapted = document.getElementById('kpiAdaptedOTD');
    if (kpiAdapted) kpiAdapted.innerText = adaptedOTD + '%';
    var sRec = document.getElementById('stratRecovery');
    if (sRec) sRec.innerText = '+' + (baseDrop * recoveryFactor).toFixed(1) + '%';

    // Keep active scenario object updated with dynamic costs
    if (scenariosData[currentScenarioKey]) {
        scenariosData[currentScenarioKey].cost = costStr;
        scenariosData[currentScenarioKey].simulated = parseFloat(simulatedOTD);
        scenariosData[currentScenarioKey].optimized = parseFloat(adaptedOTD);
    }
}

/* ── FACILITY FILTER ── */
function filterFacility(facility) {
    currentFacilityFilter = facility;
    document.querySelectorAll('.plant-btn').forEach(function(b) {
        if (b.getAttribute('data-facility') === facility) {
            b.classList.add('active');
        } else {
            b.classList.remove('active');
        }
    });
    renderMachines();
    showToast('Filtered facility: ' + (facility === 'ALL' ? 'All Plants (12 Centers)' : facility));
}

/* ── UPDATE ASSET OPTIONS BASED ON FACILITY ── */
function updateAssetOptions() {
    var facEl = document.getElementById('targetFacility');
    var assetEl = document.getElementById('targetAsset');
    if (!facEl || !assetEl) return;
    var fac = facEl.value;

