function saveCustomScenario() {
    var nameInput = document.getElementById('customScenName');
    var name = (nameInput && nameInput.value) ? nameInput.value.trim() : 'Custom Disruption';
    var fac = document.getElementById('customScenFacility').value;
    var asset = document.getElementById('customScenAsset').value;
    var dur = parseInt(document.getElementById('customDurationSlider').value || 36);
    var cap = parseInt(document.getElementById('customCapacitySlider').value || 100);
    var cat = document.getElementById('customScenCategory').value;
    var strat = document.getElementById('customScenStrategy').value || 'Reroute operations and schedule overtime shift.';

    var customKey = 'SIM-CUSTOM-' + Math.floor(Math.random() * 899 + 100);
    var baseDrop = ((dur / 48.0) * (cap / 100.0) * 22.5).toFixed(1);
    if (parseFloat(baseDrop) < 5.0) baseDrop = '5.0';
    if (parseFloat(baseDrop) > 38.0) baseDrop = '38.0';
    var simOTD = (96.5 - parseFloat(baseDrop)).toFixed(1);
    var optOTD = (parseFloat(simOTD) + (parseFloat(baseDrop) * 0.93)).toFixed(1);
    if (parseFloat(optOTD) > 96.5) optOTD = '96.5';

    var customOrders = [
        { ref: 'CUST/' + fac.substring(0,3).toUpperCase() + '/2026-901', cust: 'Custom Priority Client A', prod: 'DN80 Class 300 Valve', fac: fac, qty: 35, base: '2026-10-22', sim: '2026-10-29 (+' + Math.round(dur/24) + 'd)', opt: '2026-10-23 (+1d)', saved: Math.round(dur/24) + ' Days Saved', cell: asset + ' (Rerouted)', otd: 'On-Time Guaranteed' },
        { ref: 'CUST/' + fac.substring(0,3).toUpperCase() + '/2026-902', cust: 'Custom Priority Client B', prod: 'DN50 High Pressure Trim', fac: fac, qty: 20, base: '2026-10-26', sim: '2026-11-02 (+' + Math.round(dur/24) + 'd)', opt: '2026-10-27 (+1d)', saved: Math.round(dur/24) + ' Days Saved', cell: asset, otd: 'Minor Delay Mitigated' }
    ];

    scenariosData[customKey] = {
        title: fac + ' Facility • ' + name,
        modelName: customKey + ' (' + name + ')',
        facility: fac,
        asset: asset,
        duration: dur,
        cap: cap,
        cat: cat,
        baseline: 96.5,
        simulated: parseFloat(simOTD),
        optimized: parseFloat(optOTD),
        cost: '&#8377;38,000',
        drop: baseDrop + '%',
        recovery: '+' + (parseFloat(baseDrop) * 0.93).toFixed(1) + '%',
        strategy: strat,
        downMachine: asset,
        rerouteMachine: (fac === 'Hyderabad' ? 'MC-HYD-CNC-01' : (fac === 'Chennai' ? 'MC-CHN-CNC-01' : 'MC-BLR-CNC-01')),
        orders: customOrders
    };

    // Add to dropdown selects
    ['scenarioSelector', 'simViewScenarioSelect'].forEach(function(sId) {
        var sel = document.getElementById(sId);
        if (sel) {
            var opt = document.createElement('option');
            opt.value = customKey;
            opt.innerText = customKey + ': ' + name;
            sel.appendChild(opt);
            sel.value = customKey;
        }
    });

    loadScenario(customKey);
    closeCustomScenarioDrawer();
    showToast('Saving custom scenario directly to x_2056099_indust_0_sim_scenario...');
    uploadScenarioToServiceNow('evaluated', function() {
        showToast('\u2714 Custom Scenario ' + customKey + ' saved to ServiceNow table & loaded!');
    });
}

