    var el;
    el = document.getElementById('maintAssetCode'); if (el) el.innerText = m.code;
    el = document.getElementById('maintAssetName'); if (el) el.innerText = m.name + ' (' + m.facility + ')';
    el = document.getElementById('maintCrew'); if (el) el.innerText = m.crew;
    el = document.getElementById('maintTemp'); if (el) el.innerHTML = m.temp + '&#176;C';
    el = document.getElementById('maintVib'); if (el) el.innerText = m.vib + ' mm/s';
    el = document.getElementById('maintLoad'); if (el) el.innerText = m.load + '%';

    var descEl = document.getElementById('maintShortDesc');
    if (descEl) {
        descEl.value = '[Digital Twin Alert] Emergency Maintenance on ' + m.code + ' - Temp ' + m.temp + '\u00B0C, Vibration ' + m.vib + ' mm/s';
    }

