function confirmMaintenanceDispatch() {
    var m = currentDispatchMachine || machines[1];
    var incRef = 'INC001' + Math.floor(Math.random() * 8999 + 1000);
    var shortDesc = document.getElementById('maintShortDesc') ? document.getElementById('maintShortDesc').value : ('Emergency Dispatch: ' + m.code);

    var payload = {
        short_description: shortDesc,
        description: 'Automated telemetry alert from Digital Twin:\n- Asset: ' + m.code + ' (' + m.name + ')\n- Plant: ' + m.facility + '\n- Temperature: ' + m.temp + '°C\n- Vibration: ' + m.vib + ' mm/s\n- Load: ' + m.load + '%\n- Assigned Crew: ' + m.crew,
        urgency: '1',
        impact: '1',
        priority: '1',
        comments: 'Auto-dispatched via What-If Digital Twin Portal'
    };

    var headers = { 'Content-Type': 'application/json', 'Accept': 'application/json' };
    if (typeof window !== 'undefined' && window.g_ck) headers['X-UserToken'] = window.g_ck;

    fetch('/api/now/table/incident', {
        method: 'POST',
        headers: headers,
        body: JSON.stringify(payload)
    }).then(function(res) {
        return res.json();
    }).then(function(data) {
        var realNum = (data && data.result && data.result.number) ? data.result.number : incRef;
        m.dispatched = true;
        m.incidentRef = realNum;
        renderMachines();
        closeMaintenanceModal();
        showToast('\u2714 High-Priority Work Order #' + realNum + ' dispatched to ' + m.crew + '!');
    }).catch(function(err) {
        m.dispatched = true;
        m.incidentRef = incRef;
        renderMachines();
        closeMaintenanceModal();
        showToast('\u2714 Work Order #' + incRef + ' dispatched to ' + m.crew + ' (ServiceNow Incidents)');
    });
}

