/* ── SERVICENOW TABLE API INTEGRATION (PERSIST TO TABLES) ── */
function uploadScenarioToServiceNow(status, onSuccess) {
    var sc = scenariosData[currentScenarioKey] || scenariosData['SIM-2026-001'];
    var dSlider = document.getElementById('durationSlider');
    var cSlider = document.getElementById('capacitySlider');
    var duration = dSlider ? parseInt(dSlider.value) : (sc.duration || 48);
    var capLost = cSlider ? parseInt(cSlider.value) : (sc.cap || 100);

    var baseDrop = (duration / 48.0) * (capLost / 100.0) * 22.5;
    baseDrop = Math.min(Math.max(baseDrop, 5.0), 38.0);
    var simulatedOTD = (96.5 - baseDrop).toFixed(1);
    var adaptedOTD = (parseFloat(simulatedOTD) + (baseDrop * 0.93)).toFixed(1);
    if (parseFloat(adaptedOTD) > 96.5) adaptedOTD = '96.5';

    var targetAsset = document.getElementById('targetAsset') ? document.getElementById('targetAsset').value : sc.asset;

    var payload = {
        scenario_id: currentScenarioKey,
        scenario_name: sc.modelName || sc.title,
        disruption_category: sc.cat || 'machine_breakdown',
        target_entity: targetAsset,
        disruption_parameter: 'Duration: ' + duration + 'h, Capacity Lost: ' + capLost + '%',
        baseline_otd: parseFloat(sc.baseline || 96.5),
        simulated_otd_unmitigated: parseFloat(simulatedOTD),
        optimized_otd: parseFloat(adaptedOTD),
        recommended_strategy: sc.strategy,
        cost_delta: sc.cost || '42000',
        impacted_order_count: sc.orders ? sc.orders.length : 3,
        simulation_status: status || 'evaluated'
    };

    var headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    };
    if (typeof window !== 'undefined' && window.g_ck) {
        headers['X-UserToken'] = window.g_ck;
    }

    var queryUrl = '/api/now/table/x_2056099_indust_0_sim_scenario?sysparm_query=scenario_id=' + encodeURIComponent(currentScenarioKey) + '&sysparm_limit=1';

    fetch(queryUrl, { method: 'GET', headers: headers })
        .then(function(res) {
            if (!res.ok) throw new Error('HTTP ' + res.status);
            return res.json();
        })
        .then(function(data) {
            if (data && data.result && data.result.length > 0) {
                var sysId = data.result[0].sys_id;
                return fetch('/api/now/table/x_2056099_indust_0_sim_scenario/' + sysId, {
                    method: 'PATCH',
                    headers: headers,
                    body: JSON.stringify(payload)
                });
            } else {
                return fetch('/api/now/table/x_2056099_indust_0_sim_scenario', {
                    method: 'POST',
                    headers: headers,
                    body: JSON.stringify(payload)
                });
            }
        })
        .then(function(res) {
            if (!res.ok) throw new Error('HTTP ' + res.status);
            return res.json();
        })
        .then(function(saveResult) {
            console.log('[Digital Twin] Saved to x_2056099_indust_0_sim_scenario:', saveResult);
            if (onSuccess) onSuccess(saveResult);
        })
        .catch(function(err) {
            console.warn('[Digital Twin] REST save warning:', err);
            if (typeof GlideRecord !== 'undefined') {
                try {
                    var gr = new GlideRecord('x_2056099_indust_0_sim_scenario');
                    gr.addQuery('scenario_id', currentScenarioKey);
                    gr.query(function(existing) {
                        if (existing.next()) {
                            for (var k in payload) existing.setValue(k, payload[k]);
                            existing.update();
                        } else {
                            gr.initialize();
                            for (var k2 in payload) gr.setValue(k2, payload[k2]);
                            gr.insert();
                        }
                        if (onSuccess) onSuccess();
                    });
                    return;
                } catch(e) {
                    console.warn('GlideRecord fallback failed:', e);
                }
            }
            if (onSuccess) onSuccess();
        });
}

function uploadOrdersToServiceNow(parentSysId, callback) {
    var sc = scenariosData[currentScenarioKey] || scenariosData['SIM-2026-001'];
    if (!sc.orders || !sc.orders.length) {
        if (callback) callback();
        return;
    }

    var headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    };
    if (typeof window !== 'undefined' && window.g_ck) {
        headers['X-UserToken'] = window.g_ck;
    }

    var promises = sc.orders.map(function(o) {
        var orderRow = {
            scenario: parentSysId || currentScenarioKey,
            customer_order_ref: o.ref,
            customer_name: o.cust,
            product_bom: o.prod,
            target_facility: o.fac,
            order_qty: parseInt(o.qty),
            baseline_planned_finish: o.base,
            simulated_finish: (o.sim || '').split(' ')[0],
            adapted_finish: (o.opt || '').split(' ')[0],
            net_delay_recovered: o.saved,
            assigned_machine: o.cell,
            final_otd_status: o.otd
        };

        return fetch('/api/now/table/x_2056099_indust_0_sim_schedule_run', {
            method: 'POST',
            headers: headers,
            body: JSON.stringify(orderRow)
        }).catch(function(e) { console.warn('Order save err:', e); });
    });

    Promise.all(promises).then(function() {
        if (callback) callback();
    });
}

