/* ── LIVE TELEMETRY STREAM & PULSE TOGGLE ── */
function toggleTelemetry() {
    isLiveStreaming = !isLiveStreaming;
    var dot = document.getElementById('pulseDot');
    var lbl = document.getElementById('telemetryLabel');

    if (isLiveStreaming) {
        if (dot) {
            dot.style.background = '#10b981';
            dot.style.boxShadow = '0 0 6px #10b981';
        }
        if (lbl) lbl.innerText = 'Live Telemetry (2.5s)';
        startTelemetry();
        showToast('Live telemetry stream resumed');
    } else {
        if (dot) {
            dot.style.background = '#94a3b8';
            dot.style.boxShadow = 'none';
        }
        if (lbl) lbl.innerText = 'Telemetry Paused';
        clearInterval(liveTimer);
        showToast('Live telemetry stream paused');
    }
}

function startTelemetry() {
    clearInterval(liveTimer);
    liveTimer = setInterval(function() {
        if (!isLiveStreaming) return;
        machines.forEach(function(m) {
            var delta = (Math.random() * 0.6 - 0.3).toFixed(1);
            var newTemp = (parseFloat(m.temp) + parseFloat(delta)).toFixed(1);
            var el = document.getElementById('temp_' + m.code);
            if (el) el.innerHTML = newTemp + '&#176;C';
        });
    }, 2500);
}

/* ── TOAST NOTIFICATION ── */
function showToast(msg) {
    var toast = document.getElementById('portalToast');
    var msgEl = document.getElementById('portalToastMsg');
    if (!toast || !msgEl) return;
    msgEl.innerText = msg;
    toast.classList.add('show');
    setTimeout(function() {
        toast.classList.remove('show');
    }, 3200);
}

/* ── INITIALIZATION ── */
document.addEventListener('DOMContentLoaded', function() {
    renderMachines();
    renderOrders();
    renderStrategyMatrix();
    updateDigitalTwinMetrics();
    recalculateLiveImpact();
    startTelemetry();
});
